import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getCards, deleteCard } from '../services/api';

const CardList = () => {
  const navigate = useNavigate();
  const [cards, setCards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [hoveredCard, setHoveredCard] = useState(null);
  const [detailPosition, setDetailPosition] = useState({ top: 0, left: 0 });

  useEffect(() => {
    const fetchCards = async () => {
      try {
        const data = await getCards();
        setCards(data);
        setLoading(false);
      } catch (err) {
        setError('Failed to fetch cards. Please try again later.');
        setLoading(false);
      }
    };

    fetchCards();
  }, []);

  const handleEdit = (id, e) => {
    e.stopPropagation(); // Prevent triggering card hover
    navigate(`/edit/${id}`);
  };

  const handleDelete = async (id, e) => {
    e.stopPropagation(); // Prevent triggering card hover
    if (window.confirm('Are you sure you want to delete this card?')) {
      try {
        await deleteCard(id);
        setCards(cards.filter(card => card._id !== id));
      } catch (err) {
        setError('Failed to delete card. Please try again later.');
      }
    }
  };

  const handleMouseEnter = (card, e) => {
    const cardElement = e.currentTarget;
    const rect = cardElement.getBoundingClientRect();

    setHoveredCard(card);
    setDetailPosition({
      top: rect.top + window.scrollY,
      left: rect.right + window.scrollX + 10 // Position just 10px to the right of the card
    });
  };

  if (loading) {
    return <div className="loading">Loading cards...</div>;
  }

  if (error) {
    return <div className="error-message">{error}</div>;
  }

  return (
    <div className="card-list-page">
      <div className="header">
        <h1>Digital Cards Collection</h1>
        <Link to="/create" className="btn">Create New Card</Link>
      </div>

      {cards.length === 0 ? (
        <div className="no-cards">
          <p>No cards found. Create your first card!</p>
        </div>
      ) : (
        <div className="card-grid">
          {cards.map(card => (
            <div 
              className="card-container" 
              key={card._id}
              onMouseEnter={(e) => handleMouseEnter(card, e)}
              onMouseLeave={() => setHoveredCard(null)}
            >
              <div className="card">
                <img 
                  src={card.imageUrl} 
                  alt={card.title} 
                  className="card-image" 
                />
                <div className="card-actions">
                  <button 
                    className="btn btn-edit"
                    onClick={(e) => handleEdit(card._id, e)}
                  >
                    Edit
                  </button>
                  <button 
                    className="btn btn-danger"
                    onClick={(e) => handleDelete(card._id, e)}
                  >
                    Delete
                  </button>
                </div>
              </div>

              {hoveredCard && hoveredCard._id === card._id && (
                <div 
                  className="card-detail"
                  style={{
                    position: 'fixed',
                    top: `${detailPosition.top}px`,
                    left: `${detailPosition.left}px`,
                    opacity: 1,
                    visibility: 'visible',
                    zIndex: 100 // Ensure it's always on top
                  }}
                >
                  <h3 className="card-title">{card.title}</h3>
                  <p className="card-description">{card.description}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CardList;
